public final class EquipmentContent {
    private static final DeferredRegister<DataComponentType<?>> COMPONENTS=DeferredRegister.create(Registries.DATA_COMPONENT_TYPE,Thaumcraft.MODID);
    public static final RegistryObject<DataComponentType<Integer>> RUNIC=COMPONENTS.register("runic_shield",()->DataComponentType.<Integer>builder().persistent(Codec.intRange(0,9)).networkSynchronized(ByteBufCodecs.VAR_INT).build());
    public static final RegistryObject<DataComponentType<Integer>> TRAVEL_ENERGY=COMPONENTS.register("traveller_energy",()->DataComponentType.<Integer>builder().persistent(Codec.intRange(0,60)).networkSynchronized(ByteBufCodecs.VAR_INT).build());
    private static final Map<String,Integer> DISCOUNTS=new HashMap<>();
    private static final Set<String> REPAIR=new HashSet<>();
    private static ArmorMaterial material(String name,int durability,int boots,int legs,int chest,int head,int enchant,float toughness,String repair){return new ArmorMaterial(durability,Map.of(ArmorType.BOOTS,boots,ArmorType.LEGGINGS,legs,ArmorType.CHESTPLATE,chest,ArmorType.HELMET,head),enchant,SoundEvents.ARMOR_EQUIP_IRON,toughness,0,TagKey.create(Registries.ITEM,SimpleContent.id(repair)),ResourceKey.create(EquipmentAssets.ROOT_ID,SimpleContent.id(name)));}
    private static void armor(String name,ArmorMaterial material,ArmorType type,int discount,boolean repair){SimpleContent.item(name,p->new EquipmentArmor(p.humanoidArmor(material,type).rarity(Rarity.UNCOMMON),name));if(discount>0)DISCOUNTS.put(name,discount);if(repair)REPAIR.add(name);}
    private static final EquipmentSlot[] ARMOR={EquipmentSlot.HEAD,EquipmentSlot.CHEST,EquipmentSlot.LEGS,EquipmentSlot.FEET};
    public static String name(ItemStack s){var id=BuiltInRegistries.ITEM.getKey(s.getItem());return id.getNamespace().equals("thaumcraft")?id.getPath():"";}
    public static Map<String,Integer> cultAspects(net.minecraft.server.level.ServerLevel l,ItemStack s){String n=name(s);if(!n.startsWith("crimson_"))return null;boolean robe=n.startsWith("crimson_robe_");Item base=n.equals("crimson_blade")?Items.IRON_SWORD:n.equals("crimson_boots")?Items.IRON_BOOTS:n.endsWith("helm")?(robe?Items.LEATHER_HELMET:Items.IRON_HELMET):n.endsWith("chest")?(robe?Items.LEATHER_CHESTPLATE:Items.IRON_CHESTPLATE):robe?Items.LEATHER_LEGGINGS:Items.IRON_LEGGINGS;var out=new TreeMap<>(thaumcraft.alchemy.AspectResolver.item(l,new ItemStack(base)));out.merge("alienis",n.startsWith("crimson_praetor_")||n.equals("crimson_blade")?10:5,Integer::sum);if(robe)out.merge("praecantatio",5,Integer::sum);if(n.equals("crimson_blade"))out.merge("mortuus",10,Integer::sum);return Map.copyOf(out);}
    public static float visCost(Player p,float base){int discount=0;for(var slot:ARMOR)discount+=DISCOUNTS.getOrDefault(name(p.getItemBySlot(slot)),0);if(EquipmentContent.name(p.getItemBySlot(EquipmentSlot.HEAD)).equals("fortress_helm")&&p.getItemBySlot(EquipmentSlot.HEAD).getOrDefault(FortressMasks.GOGGLES.get(),false))discount+=5;for(var accessory:AccessorySlots.equipped(p))if(name(accessory).equals("ring_apprentice"))discount+=5;if(!AccessorySlots.find(p,"charm_voidseer").isEmpty()&&p instanceof ServerPlayer real){var warp=thaumcraft.persistence.PlayerWarpStore.read(real).result();if(warp.isPresent())discount+=Math.min(25,warp.get().permanent()/4);}
        int exhaustion=0;for(var effect:java.util.List.of(thaumcraft.taint.TaintContent.EXHAUST,thaumcraft.taint.TaintContent.INFECTIOUS)){var active=p.getEffect(effect.getHolder().orElseThrow());if(active!=null)exhaustion=Math.max(exhaustion,active.getAmplifier()+1);}
        return base*(1-Math.min(80,discount-10*exhaustion)/100F);}
    public static int runic(ItemStack s){return s.getOrDefault(RUNIC.get(),0);}
    public static boolean canAugment(ItemStack s){return s.getCount()==1&&(s.has(net.minecraft.core.component.DataComponents.EQUIPPABLE)||s.getItem() instanceof AccessoryItem)&&runic(s)<9;}
    public static ItemStack augment(ItemStack s){if(!canAugment(s))return ItemStack.EMPTY;var out=s.copy();out.set(RUNIC.get(),runic(s)+1);return out;}
    public static int maxShield(Player p){int max=0;for(var slot:ARMOR)max+=runic(p.getItemBySlot(slot));for(var accessory:AccessorySlots.equipped(p))max+=runic(accessory);return max;}
    public static float shield(Player p){return Math.clamp(p.getPersistentData().getFloatOr("tc_runic_charge",0),0,maxShield(p));}
    public static void register(BusGroup bus){
        var cloth=material("cloth",25,1,2,3,1,25,1,"repairs_cloth");var goggles=material("goggles",25,1,2,3,1,25,1,"repairs_brass");var fortress=material("fortress",40,3,6,7,3,25,3,"repairs_thaumium");var voidArmor=material("void",10,3,6,8,3,10,1,"repairs_void");var voidRobe=material("void_robe",18,4,7,9,4,10,2,"repairs_void");
        SimpleContent.item("goggles",p->new Item(p.humanoidArmor(goggles,ArmorType.HELMET).durability(350)));DISCOUNTS.put("goggles",5);
        for(var entry:Map.of("helm",ArmorType.HELMET,"chest",ArmorType.CHESTPLATE,"legs",ArmorType.LEGGINGS,"boots",ArmorType.BOOTS).entrySet()){
            String suffix=entry.getKey();var type=entry.getValue();armor("void_"+suffix,voidArmor,type,0,true);
            if(type!=ArmorType.BOOTS){armor("fortress_"+suffix,fortress,type,0,false);armor("void_robe_"+suffix,voidRobe,type,5,true);}
            if(type!=ArmorType.HELMET)armor("cloth_"+suffix,cloth,type,type==ArmorType.BOOTS?2:3,false);
        }
        var cultPlate=material("crimson_plate",18,2,5,6,2,13,0,"repairs_iron");var cultRobe=material("crimson_robe",17,2,4,5,2,13,0,"repairs_iron");var cultLeader=material("crimson_praetor",30,3,6,7,3,20,1,"repairs_thaumium");
        for(var pair:Map.of("helm",ArmorType.HELMET,"chest",ArmorType.CHESTPLATE,"legs",ArmorType.LEGGINGS).entrySet()){armor("crimson_plate_"+pair.getKey(),cultPlate,pair.getValue(),0,false);armor("crimson_robe_"+pair.getKey(),cultRobe,pair.getValue(),1,false);armor("crimson_praetor_"+pair.getKey(),cultLeader,pair.getValue(),0,false);}armor("crimson_boots",material("crimson_boots",15,2,5,6,2,9,0,"repairs_iron"),ArmorType.BOOTS,1,false);
        SimpleContent.item("crimson_blade",p->new Item(p.sword(new ToolMaterial(BlockTags.INCORRECT_FOR_NETHERITE_TOOL,200,8,3.5F,20,TagKey.create(Registries.ITEM,SimpleContent.id("repairs_thaumium"))),3,-2.4F).rarity(Rarity.EPIC)));REPAIR.add("crimson_blade");
        net.minecraftforge.event.entity.living.LivingHurtEvent.BUS.addListener(e->{if(e.getSource().is(net.minecraft.world.damagesource.DamageTypes.PLAYER_ATTACK)&&e.getSource().getEntity() instanceof ServerPlayer p&&!thaumcraft.thaumaturgy.SpellEngine.protectedTarget(p,e.getEntity())){String weapon=name(p.getMainHandItem());if(weapon.equals("crimson_blade")||weapon.startsWith("void_")&&List.of("void_sword","void_axe","void_pick","void_shovel","void_hoe").contains(weapon))e.getEntity().addEffect(new MobEffectInstance(MobEffects.WEAKNESS,weapon.equals("void_sword")||weapon.equals("crimson_blade")?60:80));if(weapon.equals("elemental_pick"))e.getEntity().igniteForSeconds(2);if(weapon.equals("crimson_blade"))e.getEntity().addEffect(new MobEffectInstance(MobEffects.HUNGER,120));}});
        SimpleContent.item("traveller_boots",p->new TravellerBoots(p.humanoidArmor(material("traveller",25,1,2,3,1,25,1,"repairs_leather"),ArmorType.BOOTS)));
        var repair=TagKey.create(Registries.ITEM,SimpleContent.id("repairs_void"));var voidTool=new ToolMaterial(BlockTags.INCORRECT_FOR_NETHERITE_TOOL,150,8,3,10,repair);var elemental=new ToolMaterial(BlockTags.INCORRECT_FOR_DIAMOND_TOOL,1500,9,3,18,TagKey.create(Registries.ITEM,SimpleContent.id("repairs_thaumium")));var primal=new ToolMaterial(BlockTags.INCORRECT_FOR_NETHERITE_TOOL,500,8,4,20,repair);
        for(String family:List.of("void","elemental"))for(String type:List.of("sword","pick","axe","shovel","hoe")){String name=family+"_"+type;SimpleContent.item(name,p->{var m=family.equals("void")?voidTool:elemental;var properties=switch(type){case "sword"->p.sword(m,3,-2.4F);case "pick"->p.pickaxe(m,1,-2.8F);case "axe"->p.axe(m,5,-3);case "shovel"->p.shovel(m,1.5F,-3);default->p.hoe(m,-2,-1);};if(family.equals("elemental")){var values=switch(type){case "sword"->Map.of("arcing",2);case "pick"->Map.of("refining",1,"sounding",2);case "axe"->Map.of("burrowing",1,"collector",1);case "shovel"->Map.of("destructive",1);default->Map.<String,Integer>of();};properties.component(InfusionEnchantments.ENCHANTMENTS.get(),values);}return !family.equals("elemental")?new Item(properties):switch(type){case "hoe"->new ElementalHoeItem(properties);case "shovel"->new ElementalShovelItem(properties);case "axe","sword"->new ElementalUseItem(properties,type.equals("sword"));default->new Item(properties);};});if(family.equals("void"))REPAIR.add(name);}
        SimpleContent.item("primal_crusher",p->new Item(primal.applyToolProperties(p,TagKey.create(Registries.BLOCK,SimpleContent.id("mineable/primal_crusher")),3.5F,-2.8F,0).component(InfusionEnchantments.ENCHANTMENTS.get(),Map.of("destructive",1,"refining",1))));REPAIR.add("primal_crusher");
        for(String accessory:List.of("amulet_mundane","amulet_fancy","ring_mundane","ring_fancy","ring_apprentice","girdle_mundane","girdle_fancy","amulet_vis","charm_verdant","charm_verdant_life","charm_verdant_sustain","charm_voidseer","band_curiosity","ring_cloud"))SimpleContent.item(accessory,AccessoryItem::new);
        SimpleContent.item("charm_undying",p->new AccessoryItem(p.component(net.minecraft.core.component.DataComponents.DEATH_PROTECTION,new net.minecraft.world.item.component.DeathProtection(List.of(new net.minecraft.world.item.consume_effects.ClearAllStatusEffectsConsumeEffect(),new net.minecraft.world.item.consume_effects.ApplyStatusEffectsConsumeEffect(List.of(new MobEffectInstance(MobEffects.REGENERATION,900,1),new MobEffectInstance(MobEffects.ABSORPTION,100,1))))))));
        SimpleContent.item("sanity_checker",p->new Item(p.stacksTo(1)){public net.minecraft.world.InteractionResult use(net.minecraft.world.level.Level l,Player player,net.minecraft.world.InteractionHand h){if(player instanceof ServerPlayer real){if(player.isShiftKeyDown()){AccessoryMenuAccess.open(real);return net.minecraft.world.InteractionResult.SUCCESS;}var state=thaumcraft.persistence.PlayerWarpStore.read(real).result();if(state.isPresent()){var w=state.get();real.sendSystemMessage(Component.translatable("equipment.thaumcraft.warp",w.permanent(),w.normal(),w.temporary()));}}return net.minecraft.world.InteractionResult.SUCCESS;}});
        COMPONENTS.register(bus);CloudJump.register();AccessoryMenuAccess.register(bus);FortressMasks.register(bus);SpecialArmor.register();ElementalShovelItem.register(bus);TravellerMovement.register();
        net.minecraftforge.event.entity.player.PlayerXpEvent.XpChange.BUS.addListener(e->{if(e.getEntity() instanceof ServerPlayer p&&!AccessorySlots.find(p,"band_curiosity").isEmpty()&&e.getAmount()>0&&p.getRandom().nextInt(3)==0){int points=Math.min(16,Math.max(1,e.getAmount()/2));if(thaumcraft.research.ResearchService.state(p)!=null&&thaumcraft.research.KnowledgeStore.write(p,thaumcraft.research.ResearchService.state(p).addPoints("OBSERVATION","BASICS",points)))e.setAmount(e.getAmount()-Math.min(e.getAmount(),points));}});

        TickEvent.PlayerTickEvent.Post.BUS.addListener(e->{if(e.player() instanceof ServerPlayer p)tickPlayer(p);});

        LivingDamageEvent.BUS.addListener(e->{if(!(e.getEntity() instanceof ServerPlayer p)||e.getAmount()<=0||e.getSource().is(net.minecraft.tags.DamageTypeTags.BYPASSES_INVULNERABILITY))return;float charge=shield(p),used=Math.min(charge,e.getAmount());if(used>0){p.getPersistentData().putFloat("tc_runic_charge",charge-used);p.getPersistentData().putLong("tc_runic_next",p.level().getGameTime()+80);e.setAmount(e.getAmount()-used);p.level().sendParticles(net.minecraft.core.particles.ParticleTypes.ENCHANT,p.getX(),p.getY()+1,p.getZ(),10,.4,.6,.4,.1);p.sendSystemMessage(Component.translatable("equipment.thaumcraft.shield",Math.round(charge-used),maxShield(p)),true);}});
        net.minecraftforge.event.entity.player.PlayerEvent.Clone.BUS.addListener(e->{if(!e.isWasDeath()){e.getEntity().getPersistentData().putFloat("tc_runic_charge",shield(e.getOriginal()));e.getEntity().getPersistentData().putLong("tc_runic_next",e.getOriginal().getPersistentData().getLongOr("tc_runic_next",0));}});
        net.minecraftforge.event.entity.player.ItemTooltipEvent.BUS.addListener(e->{String active=name(e.getItemStack());if(active.equals("elemental_shovel"))e.getToolTip().add(Component.translatable("equipment.thaumcraft.shovel_controls"));if(active.equals("elemental_sword"))e.getToolTip().add(Component.translatable("equipment.thaumcraft.wind_use"));if(active.equals("elemental_axe"))e.getToolTip().add(Component.translatable("equipment.thaumcraft.attract_use"));if(e.getItemStack().getItem() instanceof AccessoryItem)e.getToolTip().add(Component.translatable("equipment.thaumcraft.accessory"));if(e.getItemStack().getItem() instanceof IRechargable chargeable&&chargeable.getMaxCharge(e.getItemStack(),null)>0)e.getToolTip().add(Component.translatable("equipment.thaumcraft.charge",RechargeHelper.getCharge(e.getItemStack()),chargeable.getMaxCharge(e.getItemStack(),null)));int n=runic(e.getItemStack());if(n>0)e.getToolTip().add(Component.translatable("equipment.thaumcraft.runic",n));int discount=DISCOUNTS.getOrDefault(name(e.getItemStack()),0);if(discount>0)e.getToolTip().add(Component.translatable("equipment.thaumcraft.discount",discount));if(REPAIR.contains(name(e.getItemStack())))e.getToolTip().add(Component.translatable("equipment.thaumcraft.repair"));});
    }
    public static void tickPlayer(ServerPlayer p){updateFortress(p);TravellerMovement.tick(p);if(p.tickCount%20==0){for(int i=0;i<p.getInventory().getContainerSize();i++){var s=p.getInventory().getItem(i);if(REPAIR.contains(name(s))&&s.isDamaged())s.setDamageValue(s.getDamageValue()-1);}
            var off=AccessorySlots.find(p,"amulet_vis");String accessory=name(off);
            if(accessory.equals("amulet_vis")&&p.tickCount%40==0){var candidates=new ArrayList<ItemStack>();for(int i=0;i<p.getInventory().getContainerSize();i++)candidates.add(p.getInventory().getItem(i));candidates.addAll(AccessorySlots.equipped(p));for(var candidate:candidates)if(RechargeHelper.rechargeItem(p.level(),candidate,p.blockPosition(),p,1)>0)break;}
            for(var verdant:AccessorySlots.equipped(p)){if(!name(verdant).startsWith("charm_verdant"))continue;off=verdant;accessory=name(off);if(p.tickCount%40==0){if((p.hasEffect(MobEffects.POISON)||p.hasEffect(MobEffects.WITHER))&&RechargeHelper.consumeCharge(off,p,20)){p.removeEffect(MobEffects.POISON);p.removeEffect(MobEffects.WITHER);}else if(accessory.endsWith("life")&&p.getHealth()<p.getMaxHealth()&&RechargeHelper.consumeCharge(off,p,2))p.heal(1);else if(accessory.endsWith("sustain")&&p.getFoodData().getFoodLevel()<20&&RechargeHelper.consumeCharge(off,p,2))p.getFoodData().eat(1,.2F);}}AccessorySlots.flush(p);
            var data=p.getPersistentData();float charge=shield(p);if(p.isAlive()&&charge<maxShield(p)&&p.level().getGameTime()>=data.getLongOr("tc_runic_next",0)&&AuraManager.drainVis(p.level(),p.blockPosition(),1,true)>=1){AuraManager.drainVis(p.level(),p.blockPosition(),1,false);charge=Math.min(maxShield(p),charge+1);data.putLong("tc_runic_next",p.level().getGameTime()+40);}data.putFloat("tc_runic_charge",charge);
            }
    }
    public static void updateFortress(Player p){int count=0;for(var slot:ARMOR)if(name(p.getItemBySlot(slot)).startsWith("fortress_"))count++;fortressAttribute(p,net.minecraft.world.entity.ai.attributes.Attributes.ARMOR,count*(1+(FortressMasks.worn(p)>=0?1:0)));fortressAttribute(p,net.minecraft.world.entity.ai.attributes.Attributes.ARMOR_TOUGHNESS,count);}
    private static void fortressAttribute(Player p,net.minecraft.core.Holder<net.minecraft.world.entity.ai.attributes.Attribute> type,double amount){var a=p.getAttribute(type);if(a==null)return;var id=net.minecraft.resources.Identifier.parse("thaumcraft:fortress_set");var old=a.getModifier(id);if(old!=null&&old.amount()==amount)return;if(old!=null)a.removeModifier(id);if(amount>0)a.addTransientModifier(new net.minecraft.world.entity.ai.attributes.AttributeModifier(id,amount,net.minecraft.world.entity.ai.attributes.AttributeModifier.Operation.ADD_VALUE));}
    public static final class TravellerBoots extends Item implements IRechargable {public TravellerBoots(Properties p){super(p);}public int getMaxCharge(ItemStack s,LivingEntity e){return 240;}}
}
